head.script:
// ============================================================
// [XPlatform 원본 스크립트 - 주석으로 보존]
// ============================================================
// 
// function DatasetBinding_onload(obj:Form,e:LoadEventInfo) { var r = dsMain.addRow(); dsMain.setColumn(r,"NAME","New"); trace(dsMain.getColumn(0,"NAME")); }
// 
// 
// ============================================================

// ============================================================
// [WebSquare 변환 스크립트 - 1차 변환]
// 운영 적용 전에 TODO 표시 항목을 확인하세요.
// ============================================================
var scwin = (typeof scwin === "undefined") ? {} : scwin;

// TODO: WebSquare submission을 구성한 뒤 이 호환 함수를 교체하세요.
scwin.xpTransaction = function() {
    console.warn("[마이그레이션 TODO] XPlatform transaction 호출을 WebSquare submission으로 변환해야 합니다.", arguments);
};

// XPlatform Dataset.addRow() 반환 index 의미를 보존하기 위한 DataList 호환 helper.
scwin.xpAddDataListRow = function(dataList) {
    var row = dataList.getRowCount();
    dataList.insertRow(row);
    return row;
};


scwin.DatasetBinding_onload = function(e) { var r = scwin.xpAddDataListRow(dsMain); dsMain.setCellData(r,"NAME","New"); console.log(dsMain.getCellData(0,"NAME")); }


// Phase 3: Dataset itemset binding bootstrap.
scwin.__xpws_initBindings = function() {
    dsMain.setRowPosition(0);
    cboCode.setNodeSet("data:dsCode", "NM", "CD");
    rdoCode.setNodeSet("data:dsCode", "NM", "CD");
};

scwin.__xpws_onpageload = function(e) {
    scwin.__xpws_initBindings();
    if (typeof scwin.DatasetBinding_onload === "function") {
        return scwin.DatasetBinding_onload(e);
    }
};
